<?php need('manage_media'); ?>
<section class="panel"><div class="panel-head"><div><h2><?=e(le_text('Media Uploader'))?></h2><p><?=e(le_text('Twoje zdjęcia na hostingu tej witryny — gotowe do wykorzystania w Newsach.'))?></p></div><button type="button" class="btn primary" data-media-open="library"><?=e(le_text('Wgraj zdjęcia / otwórz bibliotekę'))?></button></div>
<p class="hint"><?=e(le_text('W edytorze Newsa kliknij „Dodaj obrazek”, aby wstawić plik z biblioteki. Możesz również wybrać go jako miniaturę wpisu.'))?></p>
<div class="media-grid"><?php foreach($tabData['media'] as $m): ?><article class="media-card"><img src="<?=e(le_image_thumb_url($m['path']))?>" alt="<?=e($m['alt_text']??'')?>" loading="lazy"><div class="media-body"><b><?=e($m['title']?:le_text('Bez tytułu'))?></b><small><?=e($m['mime']??'')?> · <?=number_format((int)$m['size_bytes']/1024,0,',',' ')?> KB</small><button type="button" class="btn copy-media" data-copy="<?=e($m['path'])?>">Kopiuj adres</button><form method="post" onsubmit="return confirm(<?=e(json_encode(le_text('Usunąć obrazek z biblioteki?'),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP))?>)"><?=csrf_field()?><input type="hidden" name="action" value="media_delete"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="btn danger"><?=e(le_text('Usuń'))?></button></form></div></article><?php endforeach; ?></div>
<?php if(!$tabData['media']): ?><p class="muted"><?=e(le_text('Biblioteka jest pusta. Wgraj pierwsze zdjęcie przyciskiem powyżej.'))?></p><?php endif; ?></section>
